// SVGs are parsed in an inert document and reduced to static vector primitives.
const tags=new Set('svg g defs path rect circle ellipse line polyline polygon text tspan linearGradient radialGradient stop clipPath mask pattern symbol use title desc'.split(' '));
const attrs=new Set('display visibility id d x y x1 y1 x2 y2 cx cy r rx ry width height viewBox preserveAspectRatio points fill stroke stroke-width stroke-linecap stroke-linejoin stroke-miterlimit stroke-dasharray stroke-dashoffset fill-rule clip-rule opacity fill-opacity stroke-opacity transform gradientTransform gradientUnits offset stop-color stop-opacity spreadMethod clip-path clipPathUnits mask maskUnits maskContentUnits patternUnits patternContentUnits patternTransform font-family font-size font-weight font-style text-anchor dominant-baseline dx dy rotate vector-effect'.split(' '));
const safeValue=v=>!/[<>]/.test(v)&&!/(?:javascript|data|https?|file):|@import|expression\s*\(/i.test(v)&&!(/url\s*\(/i.test(v)&&!/^(?:url\(\s*['"]?#[\w:.-]+['"]?\s*\))$/.test(v));
export function sanitizeSVG(raw,prefix){if(raw.length>2000000)throw Error('SVG 文件请保持在 2 MB 以内。');const doc=new DOMParser().parseFromString(raw,'image/svg+xml');const root=doc.documentElement;if(root.localName!=='svg'||doc.querySelector('parsererror'))throw Error('无法读取 SVG 文件。');
 // Illustrator often puts its static vector fallback inside <switch>. Keep the
 // vector children, while the allowlist below still removes foreignObject.
 for(const el of [...doc.querySelectorAll('switch')]){const group=doc.createElementNS('http://www.w3.org/2000/svg','g');for(const child of [...el.childNodes])group.appendChild(child);el.replaceWith(group);}
 // Convert basic class styles before removing stylesheets, so SVG classes cannot affect the app.
 for(const style of [...doc.querySelectorAll('style')]){for(const rule of style.textContent.matchAll(/([^{}]+)\{([^{}]+)\}/g)){const selector=rule[1].trim();if(!/^[.#\w\s,>-]+$/.test(selector))continue;try{for(const el of doc.querySelectorAll(selector))el.setAttribute('style',(el.getAttribute('style')||'')+';'+rule[2]);}catch{}}style.remove();}
 for(const el of [root,...root.querySelectorAll('*')]){if(!tags.has(el.localName)||el.namespaceURI!=='http://www.w3.org/2000/svg'){el.remove();continue;}const style=el.getAttribute('style');if(style)for(const part of style.split(';')){const idx=part.indexOf(':');if(idx<0)continue;const k=part.slice(0,idx).trim(),v=part.slice(idx+1).trim();if(attrs.has(k)&&safeValue(v))el.setAttribute(k,v);}
 for(const at of [...el.attributes]){if((at.localName==='href')&&el.localName==='use'&&/^#[\w:.-]+$/.test(at.value)){el.removeAttributeNode(at);el.setAttribute('href',at.value);continue;}if(!attrs.has(at.name)||!safeValue(at.value))el.removeAttributeNode(at);}}
 const idMap=new Map();for(const el of [root,...root.querySelectorAll('[id]')])if(el.hasAttribute('id')){const old=el.getAttribute('id'),id=prefix+'-'+old.replace(/[^\w-]/g,'_');idMap.set(old,id);el.setAttribute('id',id);}
 for(const el of [root,...root.querySelectorAll('*')])for(const a of [...el.attributes]){let v=a.value.replace(/url\(\s*['"]?#([^)'"\s]+)['"]?\s*\)/g,(_,id)=>`url(#${idMap.get(id)||'missing'})`);if(a.name==='href')v='#'+(idMap.get(v.slice(1))||'missing');if(v!==a.value)el.setAttribute(a.name,v);}
 let viewBox=root.getAttribute('viewBox');if(!viewBox||viewBox.trim().split(/[ ,]+/).length!==4||!viewBox.trim().split(/[ ,]+/).every(v=>Number.isFinite(Number(v)))){const w=parseFloat(root.getAttribute('width'))||100,h=parseFloat(root.getAttribute('height'))||100;viewBox=`0 0 ${w} ${h}`;}
 const serializer=new XMLSerializer();const group=doc.createElementNS('http://www.w3.org/2000/svg','g');for(const a of [...root.attributes])if(!['viewBox','width','height','x','y','preserveAspectRatio'].includes(a.name))group.setAttribute(a.name,a.value);for(const child of [...root.childNodes])group.appendChild(child);const inner=serializer.serializeToString(group);const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}">${inner}</svg>`;return{inner,svg,viewBox};}
